[
    {
        "title": "先看限制条件",
        "description": "这是分式方程，分母不能为零，所以先写出定义域：$x-3\\ne0$，即 $x\\ne3$。",
        "bubbleText": "做分式方程，第一眼先盯分母！分母一旦是 $0$ 就没意义，所以 $x$ 绝不能等于 $3$。",
        "bubblePos": {
            "x": 610,
            "y": 170
        }
    },
    {
        "title": "去掉分母",
        "description": "两边同乘 $x-3$，得到 $(2x-3)(x-3)=1$。",
        "bubbleText": "这样做是为了把分式变成熟悉的整式方程，更容易算。但前提是前一步已经说明 $x\\ne3$。",
        "bubblePos": {
            "x": 420,
            "y": 320
        }
    },
    {
        "title": "展开并整理",
        "description": "展开左边：$(2x-3)(x-3)=2x^2-9x+9$，所以 $2x^2-9x+9=1$，整理得 $2x^2-9x+8=0$。",
        "bubbleText": "把乘法打开，再把右边的 $1$ 移过来，就得到一个二次方程了。",
        "bubblePos": {
            "x": 250,
            "y": 465
        }
    },
    {
        "title": "求出方程的解",
        "description": "因式分解：$2x^2-9x+8=(2x-1)(x-4)=0$，所以 $x=\\frac12$ 或 $x=4$。若 $x$ 是正整数，只能取 $x=4$。",
        "bubbleText": "两个解里，$\\frac12$ 虽然是正数，但不是正整数，所以题目后半段只能用 $x=4$。",
        "bubblePos": {
            "x": 560,
            "y": 470
        }
    },
    {
        "title": "列出可选整数",
        "description": "从 $1$ 到 $x$ 的整数中随机取一个数。因为 $x=4$，所以可选整数是 $1,2,3,4$。",
        "bubbleText": "后半题其实是一个简单的等可能事件：一共 4 个数，每个数被取到的机会一样。",
        "bubblePos": {
            "x": 410,
            "y": 280
        }
    },
    {
        "title": "求偶数概率",
        "description": "在 $1,2,3,4$ 中，偶数有 $2,4$ 共 $2$ 个，总数有 $4$ 个，所以概率为 $\\frac{2}{4}=\\frac12$。",
        "bubbleText": "概率就是“符合条件的个数 ÷ 总个数”。这里就是 $2\\div4=\\frac12$。",
        "bubblePos": {
            "x": 405,
            "y": 465
        }
    },
    {
        "title": "检查答案",
        "description": "最后检查：我们保留的 $x=4$ 满足“正整数”条件，且概率结果 $\\frac12$ 已约成最简分数，因此答案正确。",
        "bubbleText": "验算时主要看两件事：一是解有没有违反条件，二是概率有没有数错、分数有没有化简。",
        "bubblePos": {
            "x": 610,
            "y": 130
        }
    }
]
